vec3 v2 = vec3(p[0] - a[0], p[1] - a[1], 0);
double d00 = std::dot(v0, v0);
double d01 = std::dot(v0, v1);
double d11 = std::dot(v1, v1);
double d20 = std::dot(v2, v0);
double d21 = std::dot(v2, v1);
